# -*- coding: utf-8 -*-
"""
R1 / PTV Visum 2026
STEP 12C FLEX -- CSD2022 CountLocation GEH scorer for PRESENT CountLocations only.

This is a flexible replacement for the rigid 444-count 12C script.

Default behavior:
  - does NOT execute assignment
  - does NOT run demand, TG/TD, post-processing, 12F/14B
  - does NOT modify links, matrices, procedures, demand segments
  - writes only R1_* result UDAs on CountLocations that are present and computable
  - does NOT require all 920001..920444 CountLocations to exist
  - does NOT fail when a present CountLocation references a deleted link
  - does NOT save the .ver file

Default scope:
  R1_12C_SCOPE=reserved_present

Scope options:
  reserved_present
    Process present CountLocations with No in 920001..920444.

  all_present_with_r1_obs
    Process any present CountLocation that has R1_OBS_RPDI or R1_OBS_VALUE.

  all_present
    Process every present CountLocation. Rows without valid observed values are skipped.

Modelled volume definition:
  For each directional CSD observation, modelled value is the sum of the 12 assigned
  passenger-car demand-segment volumes on the exact directed link:

    EXOG_EE_CF, EXOG_EE_CL, EXOG_EE_CS, EXOG_EE_CS_noT,
    EXOG_EE_CW, EXOG_EE_CW_noT,
    NATIVE_CF,  NATIVE_CL,  NATIVE_CS,  NATIVE_CS_noT,
    NATIVE_CW,  NATIVE_CW_noT

  Attribute read from links:
    VOLVEH_DSEG(<DSeg>,AP)

Freight LNV/NV is audited but excluded from passenger-count GEH.
"""

from __future__ import print_function

import csv
import json
import math
import os
import re
import statistics
import traceback
import zipfile
from datetime import datetime
from pathlib import Path


SCRIPT_ID = "R1_12C_CSD2022_GEH_COLOR_SCALE_FLEX_PRESENT_20261010"

RESERVED_FIRST = 920001
RESERVED_LAST = 920444
EXPECTED_ROWS_ORIGINAL = 444
EXPECTED_CALIBRATION_ORIGINAL = 404
EXPECTED_VALIDATION_ORIGINAL = 40

FAMILIES = ("CF", "CL", "CS", "CS_noT", "CW", "CW_noT")
LAYERS = ("EXOG_EE", "NATIVE")
PASSENGER_DSEGS = tuple("%s_%s" % (layer, fam) for layer in LAYERS for fam in FAMILIES)
FREIGHT_DSEGS = ("LNV", "NV")

MODEL_SCOPE = "12PASS_DSEG_DIRECTED_AP_LNV_NV_EXCLUDED"
DEFAULT_SCOPE = "reserved_present"

RESULT_UDA_DEFS = [
