    ("R1_RATIO", "R1 Ratio", "Model divided by observed; -1 when observed=0", 2, 6),
    ("R1_GEH", "R1 GEH", "GEH statistic", 2, 3),
    ("R1_GEH_BIN", "R1 GEH Bin", "GEH color class bin 1..8; 0 when skipped", 2, 0),
    ("R1_GEH_BAND", "R1 GEH Band", "GEH color class text", 5, None),
    ("R1_GEH_COLOR", "R1 GEH Color", "Recommended color name for GEH band", 5, None),
