    {"bin": 6, "lower_inclusive": 15.0, "upper_exclusive": 17.5, "band": "<=17.5", "label": "<= 17.5", "color_name": "modra", "hex": "#1E32FF", "rgb": "30,50,255"},
    {"bin": 7, "lower_inclusive": 17.5, "upper_exclusive": 20.0, "band": "<=20", "label": "<= 20", "color_name": "svetle modra", "hex": "#28B8F0", "rgb": "40,184,240"},
    {"bin": 8, "lower_inclusive": 20.0, "upper_exclusive": None, "band": ">20", "label": "> 20", "color_name": "tyrkysova", "hex": "#66E0E0", "rgb": "102,224,224"},
