def now_stamp():
    return datetime.now().strftime("%Y%m%d_%H%M%S")


def now_text():
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def env_bool(name, default=False):
    v = os.environ.get(name)
    if v is None:
        return bool(default)
    return str(v).strip().lower() in ("1", "true", "yes", "y", "ano")


def env_str(name, default=""):
    v = os.environ.get(name)
    if v is None or str(v).strip() == "":
        return default
    return str(v).strip()


def safe_name(s):
    return re.sub(r"[^0-9A-Za-z_\-.]+", "_", str(s))


def as_int(v, default=None):
    try:
        if v is None or str(v).strip() == "":
            return default
        return int(round(float(str(v).replace(",", "."))))
    except Exception:
        return default


def as_float(v, default=None):
    try:
        if v is None or str(v).strip() == "":
            return default
        x = float(str(v).replace(",", "."))
        if not math.isfinite(x):
            return default
        return x
    except Exception:
        return default


def text(v, default=""):
    if v is None:
        return default
    return str(v)


def collection_items(coll):
    errors = []
    try:
        value = getattr(coll, "GetAll")
        if callable(value):
            value = value()
        if value is not None:
            return tuple(value)
    except Exception as exc:
        errors.append("GetAll: %s" % exc)
    try:
        return tuple(coll)
    except Exception as exc:
        errors.append("iteration: %s" % exc)
    raise RuntimeError("Could not enumerate COM collection (%s)" % " | ".join(errors))


def att(obj, names, default=None):
    if isinstance(names, str):
        names = [names]
    for name in names:
        try:
            return obj.AttValue(name)
        except Exception:
            pass
    return default


def set_att(obj, names, value, required=True):
    if isinstance(names, str):
        names = [names]
    errors = []
    for name in names:
        try:
            obj.SetAttValue(name, value)
            return name
        except Exception as exc:
            errors.append("%s: %s" % (name, exc))
    if required:
        raise RuntimeError("Could not set %r=%r (%s)" % (names, value, " | ".join(errors)))
    return None


def attr_exists(coll, attr_id):
    try:
        return bool(coll.AttrExists(attr_id))
    except Exception:
        try:
            items = collection_items(coll)
        except Exception:
            items = []
        if items:
            try:
                items[0].AttValue(attr_id)
                return True
            except Exception:
                return False
        return False


def ensure_countlocation_udas(v, out_path):
    coll = v.Net.CountLocations
    rows = []
    for attr_id, short_name, long_name, value_type, decimals in RESULT_UDA_DEFS:
        if attr_exists(coll, attr_id):
            rows.append({"ATTRIBUTE_ID": attr_id, "ACTION": "EXISTING"})
            continue
        try:
            if decimals is None:
                coll.AddUserDefinedAttribute(attr_id, short_name, long_name, value_type)
            else:
                coll.AddUserDefinedAttribute(attr_id, short_name, long_name, value_type, decimals)
        except Exception as exc:
            raise RuntimeError("Could not create CountLocation UDA %s: %s" % (attr_id, exc))
        if not attr_exists(coll, attr_id):
            raise RuntimeError("CountLocation UDA %s not visible after creation" % attr_id)
        rows.append({"ATTRIBUTE_ID": attr_id, "ACTION": "CREATED"})
    write_rows(out_path, ["ATTRIBUTE_ID", "ACTION"], rows)
    return rows


def get_visum():
    v = globals().get("Visum")
    if v is None:
        v = globals().get("COM")
    if v is not None:
        return v
    try:
        import win32com.client  # type: ignore
        for progid in ("Visum.Visum.260", "Visum.Visum.250", "Visum.Visum"):
            try:
                return win32com.client.GetActiveObject(progid)
            except Exception:
                pass
    except Exception:
        pass
    raise RuntimeError("Visum/COM global object is not available. Run inside PTV Visum 2026.")


def version_project_dir(v):
    try:
        p = str(v.GetPath(2) or "").strip()
        if p:
            q = Path(p)
            if q.suffix.lower() == ".ver":
                q = q.parent
            return q
    except Exception:
        pass
    try:
        return Path(__file__).resolve().parent
    except Exception:
        return Path.cwd()


def write_rows(path, headers, rows):
    with Path(path).open("w", newline="", encoding="utf-8-sig") as f:
        w = csv.DictWriter(f, fieldnames=headers, extrasaction="ignore", delimiter=";")
        w.writeheader()
        for r in rows:
            w.writerow({h: r.get(h, "") for h in headers})


def write_kv(path, rows):
    with Path(path).open("w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f, delimiter=";")
        w.writerow(["METRIC", "VALUE"])
        for k, v in rows:
            w.writerow([k, v])


def write_json(path, obj):
    Path(path).write_text(json.dumps(obj, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def geh(model, observed):
    model = max(0.0, float(model))
    observed = max(0.0, float(observed))
    denom = model + observed
    if denom <= 0:
        return 0.0
    return math.sqrt(2.0 * (model - observed) ** 2 / denom)


def color_band(g):
    x = float(g)
    for band in COLOR_BANDS:
        lo = band["lower_inclusive"]
        hi = band["upper_exclusive"]
        if x >= lo and (hi is None or x < hi):
            return band
    return COLOR_BANDS[-1]


def percentile(values, p):
    vals = sorted(float(x) for x in values)
    if not vals:
        return None
    if len(vals) == 1:
        return vals[0]
    pos = (len(vals) - 1) * p
    lo = int(math.floor(pos))
    hi = int(math.ceil(pos))
    if lo == hi:
        return vals[lo]
    return vals[lo] + (vals[hi] - vals[lo]) * (pos - lo)


def pct(n, d):
    return 100.0 * float(n) / float(d) if d else 0.0


def link_snapshot(v):
    rows = []
    by_key = {}
    duplicates = []
    for obj in collection_items(v.Net.Links):
        no = as_int(att(obj, ["NO", "No"]))
        fr = as_int(att(obj, ["FROMNODENO", "FromNodeNo"]))
        to = as_int(att(obj, ["TONODENO", "ToNodeNo"]))
        if no is None or fr is None or to is None:
            continue
        row = {
            "NO": no,
            "FROM": fr,
            "TO": to,
            "OBJ": obj,
            "TSYSSET": text(att(obj, ["TSYSSET", "TSysSet"], "")),
        }
        rows.append(row)
        key = (no, fr, to)
        if key in by_key:
            duplicates.append({"link_no": no, "from_node_no": fr, "to_node_no": to})
            continue
        by_key[key] = row
    return rows, by_key, duplicates


def countlocation_topology(obj):
    return {
        "link_no": as_int(att(obj, ["LINK\\NO", "LINKNO", "LinkNo"])),
        "from_no": as_int(att(obj, ["FROMNODENO", "FromNodeNo", "LINK\\FROMNODENO"])),
        "to_no": as_int(att(obj, ["TONODENO", "ToNodeNo", "LINK\\TONODENO"])),
        "relpos": as_float(att(obj, ["RELPOS", "RelPos", "RELPOSITION", "RelativePosition"])),
    }


def required_link_volume(link_obj, dseg_code, label):
    attr_id = "VOLVEH_DSEG(%s,AP)" % dseg_code
    try:
        v = link_obj.AttValue(attr_id)
    except Exception as exc:
        raise RuntimeError("Cannot read %s for %s: %s" % (attr_id, label, exc))
    x = as_float(v)
    if x is None:
        raise RuntimeError("Undefined/non-finite %s for %s: %r" % (attr_id, label, v))
    if x < -1e-9:
        raise RuntimeError("Negative %s for %s: %.12g" % (attr_id, label, x))
    return max(0.0, x)


def optional_link_volume(link_obj, attr_id):
    try:
        return as_float(link_obj.AttValue(attr_id))
    except Exception:
        return None


def compute_model(link_obj, label):
    dseg_values = {}
    total = 0.0
    by_family = dict((f, 0.0) for f in FAMILIES)
    by_layer = dict((l, 0.0) for l in LAYERS)

    for layer in LAYERS:
        for fam in FAMILIES:
            dseg = "%s_%s" % (layer, fam)
            val = required_link_volume(link_obj, dseg, label)
            dseg_values[dseg] = val
            by_family[fam] += val
            by_layer[layer] += val
            total += val

    freight = {}
    for dseg in FREIGHT_DSEGS:
        try:
            freight[dseg] = required_link_volume(link_obj, dseg, label + " QA freight")
        except Exception:
            freight[dseg] = None

    qa_tsys_c = optional_link_volume(link_obj, "VOLVEH_TSYS(C,AP)")
    qa_tsys_cnot = optional_link_volume(link_obj, "VOLVEH_TSYS(C_noT,AP)")
    qa_prt = optional_link_volume(link_obj, "VOLVEHPRT(AP)")

    return {
        "total": total,
        "dseg_values": dseg_values,
        "by_family": by_family,
        "by_layer": by_layer,
        "freight": freight,
        "qa_tsys_c": qa_tsys_c,
        "qa_tsys_cnot": qa_tsys_cnot,
        "qa_prt": qa_prt,
    }


def probe_assignment_attributes(v, out_path, sample_link_obj):
    rows = []
    bad = []
    for dseg in PASSENGER_DSEGS:
        attr_id = "VOLVEH_DSEG(%s,AP)" % dseg
        try:
            val = sample_link_obj.AttValue(attr_id)
            x = as_float(val)
            status = "OK" if x is not None else "NON_NUMERIC"
            if x is None:
                bad.append(attr_id)
        except Exception as exc:
            status = "ERROR: %s" % exc
            bad.append(attr_id)
        rows.append({"ATTRIBUTE": attr_id, "PURPOSE": "GEH_INCLUDED_PASSENGER", "STATUS": status})

    for dseg in FREIGHT_DSEGS:
        attr_id = "VOLVEH_DSEG(%s,AP)" % dseg
        try:
            sample_link_obj.AttValue(attr_id)
            status = "OK"
        except Exception as exc:
            status = "ERROR: %s" % exc
        rows.append({"ATTRIBUTE": attr_id, "PURPOSE": "QA_FREIGHT_EXCLUDED", "STATUS": status})

    for attr_id, purpose in [
        ("VOLVEH_TSYS(C,AP)", "QA_AGGREGATE_C"),
        ("VOLVEH_TSYS(C_noT,AP)", "QA_AGGREGATE_C_noT"),
        ("VOLVEHPRT(AP)", "QA_TOTAL_PRT"),
    ]:
        try:
            sample_link_obj.AttValue(attr_id)
            status = "OK"
        except Exception as exc:
            status = "ERROR: %s" % exc
        rows.append({"ATTRIBUTE": attr_id, "PURPOSE": purpose, "STATUS": status})

    write_rows(out_path, ["ATTRIBUTE", "PURPOSE", "STATUS"], rows)
    if bad:
        raise RuntimeError("Required passenger assignment attributes unavailable: %s" % ", ".join(bad[:5]))
    return rows


def summarize_group(label, rows):
    gehs = [r["geh"] for r in rows]
    obs = sum(r["observed"] for r in rows)
    model = sum(r["model"] for r in rows)
    diffs = [r["diff"] for r in rows]
    absdiffs = [abs(x) for x in diffs]
    out = {
        "group": label,
        "n": len(rows),
        "obs_sum": obs,
        "model_sum": model,
        "model_obs_ratio": (model / obs) if obs > 0 else "",
        "bias": model - obs,
        "bias_percent": (100.0 * (model - obs) / obs) if obs > 0 else "",
        "mae": statistics.mean(absdiffs) if absdiffs else "",
        "rmse": math.sqrt(statistics.mean([x * x for x in diffs])) if diffs else "",
        "geh_mean": statistics.mean(gehs) if gehs else "",
        "geh_median": statistics.median(gehs) if gehs else "",
        "geh_p85": percentile(gehs, 0.85),
        "geh_p90": percentile(gehs, 0.90),
        "geh_p95": percentile(gehs, 0.95),
        "geh_max": max(gehs) if gehs else "",
        "geh_lt_5": sum(1 for x in gehs if x < 5.0),
        "geh_5_10": sum(1 for x in gehs if 5.0 <= x < 10.0),
        "geh_10_15": sum(1 for x in gehs if 10.0 <= x < 15.0),
        "geh_15_20": sum(1 for x in gehs if 15.0 <= x < 20.0),
        "geh_20_30": sum(1 for x in gehs if 20.0 <= x < 30.0),
        "geh_ge_30": sum(1 for x in gehs if x >= 30.0),
    }
    out["geh_lt_5_percent"] = pct(out["geh_lt_5"], len(rows))
    out["geh_lt_10_percent"] = pct(out["geh_lt_5"] + out["geh_5_10"], len(rows))
    return out


def zip_outputs(zip_path, files):
    with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED) as z:
        for p in files:
            p = Path(p)
            if p.exists():
                z.write(str(p), arcname=p.name)


def countlocation_has_valid_obs(cl):
    obs = as_float(att(cl, "R1_OBS_RPDI", None))
    if obs is None:
        obs = as_float(att(cl, "R1_OBS_VALUE", None))
    return obs is not None and obs >= 0


def select_countlocations(v):
    scope = env_str("R1_12C_SCOPE", DEFAULT_SCOPE)
    cls_items = collection_items(v.Net.CountLocations)
    cls_by_no = {}

    for obj in cls_items:
        no = as_int(att(obj, ["NO", "No"]))
        if no is not None:
            cls_by_no[no] = obj

    targets = []
    for no, obj in sorted(cls_by_no.items()):
        if scope == "reserved_present":
            if RESERVED_FIRST <= no <= RESERVED_LAST:
                targets.append(obj)
        elif scope == "all_present_with_r1_obs":
            if countlocation_has_valid_obs(obj):
                targets.append(obj)
        elif scope == "all_present":
            targets.append(obj)
        else:
            raise RuntimeError("Unknown R1_12C_SCOPE=%r" % scope)

    missing_reserved = []
    for no in range(RESERVED_FIRST, RESERVED_LAST + 1):
        if no not in cls_by_no:
            missing_reserved.append({
                "countlocation_no": no,
                "status": "MISSING_IN_CURRENT_MODEL",
                "note": "Allowed by flexible 12C; profile may have been removed during network/periphery pruning.",
            })

    return targets, cls_by_no, missing_reserved, scope


def mark_skipped(cl, status, reason, timestamp):
    set_att(cl, "R1_GEH_STATUS", status, required=False)
    set_att(cl, "R1_GEH_SKIP_REASON", reason, required=False)
    set_att(cl, "R1_GEH_TS", timestamp, required=False)
    set_att(cl, "R1_GEH_BIN", 0, required=False)


def main():
    v = get_visum()
    base = version_project_dir(v)
    root = base / "R1_12C_CSD2022_GEH_COLOR_SCALE_FLEX"
    stamp = now_stamp()
    runtime = root / ("R1_12C_FLEX_%s" % stamp)
    runtime.mkdir(parents=True, exist_ok=True)

    log_file = runtime / "12c_flex_geh_color_scale.log"
    pass_file = runtime / "12c_flex_PASS.txt"
    warn_file = runtime / "12c_flex_WARNINGS.txt"
    err_file = runtime / "12c_flex_ERROR.txt"

    uda_file = runtime / "00_UDA_STATUS.csv"
    attr_file = runtime / "01_ASSIGNMENT_ATTRIBUTE_PROBE.csv"
    detail_file = runtime / "02_GEH_DETAIL_444.csv"
    detail_present_file = runtime / "02B_GEH_DETAIL_PRESENT.csv"
    summary_file = runtime / "03_GEH_SUMMARY.csv"
    role_file = runtime / "04_GEH_BY_ROLE.csv"
    band_file = runtime / "05_GEH_BANDS.csv"
    worst_file = runtime / "06_WORST_50.csv"
    color_file = runtime / "07_COLOR_SCALE_LEGEND.csv"
    readme_file = runtime / "08_VISUM_GRAPHICS_SETUP.txt"
    json_file = runtime / "09_SUMMARY.json"

    missing_reserved_file = runtime / "10_MISSING_RESERVED_COUNTLOCATIONS.csv"
    skipped_link_file = runtime / "11_SKIPPED_LINK_NOT_FOUND.csv"
    skipped_obs_file = runtime / "12_SKIPPED_INVALID_OBS.csv"
    skipped_model_file = runtime / "13_SKIPPED_MODEL_ERROR.csv"
    duplicate_links_file = runtime / "14_LINK_DUPLICATES.csv"

    latest_zip = root / "R1_12C_CSD2022_GEH_COLOR_SCALE_FLEX_LATEST.zip"

    def log(msg):
        try:
            with log_file.open("a", encoding="utf-8") as f:
                f.write("[%s] %s\n" % (now_text(), msg))
        except Exception:
            pass

    try:
        log("START %s" % SCRIPT_ID)
        timestamp = now_text()
        scope = env_str("R1_12C_SCOPE", DEFAULT_SCOPE)

        ensure_countlocation_udas(v, uda_file)

        link_rows, links_by_key, duplicate_links = link_snapshot(v)
        write_rows(duplicate_links_file, ["link_no", "from_node_no", "to_node_no"], duplicate_links)

        targets, cls_by_no, missing_reserved, scope = select_countlocations(v)
        write_rows(missing_reserved_file, ["countlocation_no", "status", "note"], missing_reserved)

        if not targets:
            raise RuntimeError("No CountLocations selected for scope=%s" % scope)

        sample_link = None
        sample_key = None
        for cl in targets:
            if not countlocation_has_valid_obs(cl):
                continue
            top = countlocation_topology(cl)
            key = (top["link_no"], top["from_no"], top["to_no"])
            if key in links_by_key:
                sample_key = key
                sample_link = links_by_key[key]["OBJ"]
                break

        if sample_link is None:
            raise RuntimeError(
                "No selected CountLocation could be matched to a current directed link with valid observed value. "
                "Selected=%d scope=%s" % (len(targets), scope)
            )

        probe_assignment_attributes(v, attr_file, sample_link)

        results = []
        skipped_link = []
        skipped_obs = []
        skipped_model = []
        role_counts = {}

        for cl in targets:
            no = as_int(att(cl, ["NO", "No"]))
            code = text(att(cl, ["CODE", "Code"], ""))
            name = text(att(cl, ["NAME", "Name"], ""))
            obs_id = text(att(cl, "R1_OBS_ID", ""))
            role = text(att(cl, "R1_ROLE", ""))
            active = as_int(att(cl, "R1_ACTIVE", 1), 1)
            rpdi_ready = as_int(att(cl, "R1_RPDI_READY", 1), 1)

            role_counts[role] = role_counts.get(role, 0) + 1

            obs = as_float(att(cl, "R1_OBS_RPDI", None))
            if obs is None:
                obs = as_float(att(cl, "R1_OBS_VALUE", None))

            top = countlocation_topology(cl)
            key = (top["link_no"], top["from_no"], top["to_no"])

            base_skip_row = {
                "countlocation_no": no,
                "code": code,
                "name": name,
                "obs_id": obs_id,
                "role": role,
                "active": active,
                "rpdi_ready": rpdi_ready,
                "link_no": key[0],
                "from_node_no": key[1],
                "to_node_no": key[2],
                "relpos": top["relpos"],
                "observed": obs if obs is not None else "",
            }

            if obs is None or obs < 0:
                reason = "Invalid or missing observed value: R1_OBS_RPDI/R1_OBS_VALUE"
                rr = dict(base_skip_row)
                rr["skip_reason"] = reason
                skipped_obs.append(rr)
                mark_skipped(cl, "SKIP_INVALID_OBS", reason, timestamp)
                continue

            if key not in links_by_key:
                reason = "Mapped directed link not found in current model; probably deleted/pruned link."
                rr = dict(base_skip_row)
                rr["skip_reason"] = reason
                skipped_link.append(rr)
                mark_skipped(cl, "SKIP_LINK_NOT_FOUND", reason, timestamp)
                continue

            link_row = links_by_key[key]
            link_obj = link_row["OBJ"]
            label = "%s %s:%s->%s" % (obs_id or no, key[0], key[1], key[2])

            try:
                model_pack = compute_model(link_obj, label)
            except Exception as exc:
                reason = "Model volume computation failed: %s" % exc
                rr = dict(base_skip_row)
                rr["skip_reason"] = reason
                skipped_model.append(rr)
                mark_skipped(cl, "SKIP_MODEL_ERROR", reason, timestamp)
                continue

            model = model_pack["total"]
            g = geh(model, obs)
            diff = model - obs
            ratio = -1.0 if obs <= 0 else model / obs
            band = color_band(g)

            set_att(cl, "R1_MODEL_BOTH", model)
            set_att(cl, "R1_MODEL_DIR", model)
            set_att(cl, "R1_MODEL_SCOPE", MODEL_SCOPE)
            set_att(cl, "R1_DIFF", diff)
            set_att(cl, "R1_ABS_DIFF", abs(diff))
            set_att(cl, "R1_RATIO", ratio)
            set_att(cl, "R1_GEH", g)
            set_att(cl, "R1_GEH_BIN", int(band["bin"]))
            set_att(cl, "R1_GEH_BAND", band["band"])
            set_att(cl, "R1_GEH_COLOR", band["color_name"])
            set_att(cl, "R1_GEH_HEX", band["hex"])
            set_att(cl, "R1_GEH_RGB", band["rgb"])
            set_att(cl, "R1_GEH_OK5", 1 if g < 5.0 else 0)
            set_att(cl, "R1_GEH_OK10", 1 if g < 10.0 else 0)
            set_att(cl, "R1_GEH_TS", timestamp)
            set_att(cl, "R1_GEH_STATUS", "PASS")
            set_att(cl, "R1_GEH_SKIP_REASON", "")

            row = {
                "countlocation_no": no,
                "code": code,
                "name": name,
                "obs_id": obs_id,
                "role": role,
                "active": active,
                "rpdi_ready": rpdi_ready,
                "link_no": key[0],
                "from_node_no": key[1],
                "to_node_no": key[2],
                "relpos": top["relpos"],
                "tsysset": link_row["TSYSSET"],
                "observed": obs,
                "model": model,
                "diff": diff,
                "abs_diff": abs(diff),
                "ratio": ratio,
                "geh": g,
                "geh_bin": int(band["bin"]),
                "geh_band": band["band"],
                "geh_color": band["color_name"],
                "geh_hex": band["hex"],
                "geh_rgb": band["rgb"],
                "model_scope": MODEL_SCOPE,
                "qa_tsys_c": model_pack["qa_tsys_c"],
                "qa_tsys_cnot": model_pack["qa_tsys_cnot"],
                "qa_tsys_c_plus_cnot": "" if model_pack["qa_tsys_c"] is None or model_pack["qa_tsys_cnot"] is None else model_pack["qa_tsys_c"] + model_pack["qa_tsys_cnot"],
                "qa_model_minus_tsys_c_plus_cnot": "" if model_pack["qa_tsys_c"] is None or model_pack["qa_tsys_cnot"] is None else model - (model_pack["qa_tsys_c"] + model_pack["qa_tsys_cnot"]),
                "qa_prt_total": model_pack["qa_prt"],
            }

            for dseg in PASSENGER_DSEGS:
                row["model_%s" % dseg] = model_pack["dseg_values"].get(dseg, 0.0)
            for fam in FAMILIES:
                row["family_%s" % fam] = model_pack["by_family"].get(fam, 0.0)
            for layer in LAYERS:
                row["layer_%s" % layer] = model_pack["by_layer"].get(layer, 0.0)
            for dseg in FREIGHT_DSEGS:
                row["qa_freight_%s_excluded" % dseg] = model_pack["freight"].get(dseg, "")

            results.append(row)

        write_rows(skipped_link_file, [
            "countlocation_no", "code", "name", "obs_id", "role", "active", "rpdi_ready",
            "link_no", "from_node_no", "to_node_no", "relpos", "observed", "skip_reason",
        ], skipped_link)

        write_rows(skipped_obs_file, [
            "countlocation_no", "code", "name", "obs_id", "role", "active", "rpdi_ready",
            "link_no", "from_node_no", "to_node_no", "relpos", "observed", "skip_reason",
        ], skipped_obs)

        write_rows(skipped_model_file, [
            "countlocation_no", "code", "name", "obs_id", "role", "active", "rpdi_ready",
            "link_no", "from_node_no", "to_node_no", "relpos", "observed", "skip_reason",
        ], skipped_model)

        if not results:
            raise RuntimeError(
                "No CountLocations were successfully scored. selected=%d skipped_link=%d skipped_obs=%d skipped_model=%d"
                % (len(targets), len(skipped_link), len(skipped_obs), len(skipped_model))
            )

        detail_fields = [
            "countlocation_no", "code", "name", "obs_id", "role", "active", "rpdi_ready",
            "link_no", "from_node_no", "to_node_no", "relpos", "tsysset",
            "observed", "model", "diff", "abs_diff", "ratio", "geh",
            "geh_bin", "geh_band", "geh_color", "geh_hex", "geh_rgb", "model_scope",
        ]
        for dseg in PASSENGER_DSEGS:
            detail_fields.append("model_%s" % dseg)
        for fam in FAMILIES:
            detail_fields.append("family_%s" % fam)
        for layer in LAYERS:
            detail_fields.append("layer_%s" % layer)
        detail_fields += [
            "qa_freight_LNV_excluded", "qa_freight_NV_excluded", "qa_tsys_c", "qa_tsys_cnot",
            "qa_tsys_c_plus_cnot", "qa_model_minus_tsys_c_plus_cnot", "qa_prt_total",
        ]

        write_rows(detail_file, detail_fields, results)
        write_rows(detail_present_file, detail_fields, results)

        summary_all = summarize_group("ALL_PROCESSED_PRESENT", results)
        summary_rows = [(k, v) for k, v in summary_all.items()]
        summary_rows += [
            ("script_id", SCRIPT_ID),
            ("timestamp", timestamp),
            ("scope", scope),
            ("original_countlocation_range", "%d..%d" % (RESERVED_FIRST, RESERVED_LAST)),
            ("original_expected_rows_not_enforced", EXPECTED_ROWS_ORIGINAL),
            ("present_selected_countlocations", len(targets)),
            ("processed_countlocations", len(results)),
            ("missing_reserved_countlocations", len(missing_reserved)),
            ("skipped_link_not_found", len(skipped_link)),
            ("skipped_invalid_obs", len(skipped_obs)),
            ("skipped_model_error", len(skipped_model)),
            ("role_counts_actual", json.dumps(role_counts, ensure_ascii=False, sort_keys=True)),
            ("model_scope", MODEL_SCOPE),
            ("passenger_dsegs", "|".join(PASSENGER_DSEGS)),
            ("freight_excluded", "|".join(FREIGHT_DSEGS)),
            ("assignment_executed_by_script", False),
            ("version_saved", False),
            ("mutated_countlocation_result_udas", True),
        ]
        write_kv(summary_file, summary_rows)

        role_summary = [
            summarize_group(role, [r for r in results if r["role"] == role])
            for role in sorted(set(r["role"] for r in results))
        ]
        role_fields = list(summarize_group("ALL_PROCESSED_PRESENT", results).keys())
        write_rows(role_file, role_fields, role_summary)

        band_rows = []
        for band in COLOR_BANDS:
            rr = [r for r in results if r["geh_bin"] == band["bin"]]
            band_rows.append({
                "geh_bin": band["bin"],
                "band": band["band"],
                "lower_inclusive": band["lower_inclusive"],
                "upper_exclusive": "" if band["upper_exclusive"] is None else band["upper_exclusive"],
                "label": band["label"],
                "color_name": band["color_name"],
                "hex": band["hex"],
                "rgb": band["rgb"],
                "count": len(rr),
                "percent": pct(len(rr), len(results)),
                "obs_sum": sum(x["observed"] for x in rr),
                "model_sum": sum(x["model"] for x in rr),
            })
        write_rows(band_file, [
            "geh_bin", "band", "lower_inclusive", "upper_exclusive", "label",
            "color_name", "hex", "rgb", "count", "percent", "obs_sum", "model_sum",
        ], band_rows)
        write_rows(color_file, [
            "geh_bin", "band", "lower_inclusive", "upper_exclusive", "label",
            "color_name", "hex", "rgb",
        ], COLOR_BANDS)

        worst = sorted(results, key=lambda r: (-r["geh"], r["countlocation_no"]))[:50]
        worst_fields = [
            "rank", "countlocation_no", "code", "obs_id", "role",
            "link_no", "from_node_no", "to_node_no",
            "observed", "model", "diff", "ratio", "geh",
            "geh_bin", "geh_band", "geh_color",
        ]
        worst_rows = []
        for i, r in enumerate(worst, 1):
            row = {k: r.get(k, "") for k in worst_fields}
            row["rank"] = i
            worst_rows.append(row)
        write_rows(worst_file, worst_fields, worst_rows)

        readme_file.write_text(
            "R1 12C FLEX -- GEH graphics setup\n"
            "=================================\n\n"
            "The script computed R1_GEH only for CountLocations present in the current model and computable on current directed links.\n\n"
            "Recommended Visum graphics setup:\n"
            "1. Open Graphic parameters for CountLocations.\n"
            "2. Set symbol/fill color by attribute R1_GEH_BIN or directly by R1_GEH.\n"
            "3. Use 07_COLOR_SCALE_LEGEND.csv for classes.\n\n"
            "Skipped rows are exported separately:\n"
            "- 10_MISSING_RESERVED_COUNTLOCATIONS.csv\n"
            "- 11_SKIPPED_LINK_NOT_FOUND.csv\n"
            "- 12_SKIPPED_INVALID_OBS.csv\n"
            "- 13_SKIPPED_MODEL_ERROR.csv\n\n"
            "The script did not execute assignment and did not save the .ver.\n",
            encoding="utf-8",
        )

        status = "PASS_FLEX"
        warnings = []
        if missing_reserved:
            warnings.append("missing_reserved_countlocations=%d" % len(missing_reserved))
        if skipped_link:
            warnings.append("skipped_link_not_found=%d" % len(skipped_link))
        if skipped_obs:
            warnings.append("skipped_invalid_obs=%d" % len(skipped_obs))
        if skipped_model:
            warnings.append("skipped_model_error=%d" % len(skipped_model))
        if sum(r["model"] for r in results) <= 1e-9:
            status = "PASS_FLEX_WARN_ALL_MODELLED_PASSENGER_ZERO"
            warnings.append("all_modelled_passenger_volumes_zero_run_assignment_or_check_assignment_results")
        elif warnings:
            status = "PASS_FLEX_WITH_SKIPS"

        warn_file.write_text("\n".join(warnings) + ("\n" if warnings else ""), encoding="utf-8")

        summary_obj = {
            "script_id": SCRIPT_ID,
            "timestamp": timestamp,
            "status": status,
            "scope": scope,
            "countlocations_present_selected": len(targets),
            "countlocations_processed": len(results),
            "missing_reserved_countlocations": len(missing_reserved),
            "skipped_link_not_found": len(skipped_link),
            "skipped_invalid_obs": len(skipped_obs),
            "skipped_model_error": len(skipped_model),
            "role_counts_actual": role_counts,
            "summary": summary_all,
            "bands": band_rows,
            "model_scope": MODEL_SCOPE,
            "passenger_dsegs": list(PASSENGER_DSEGS),
            "freight_excluded": list(FREIGHT_DSEGS),
            "assignment_executed_by_script": False,
            "version_saved": False,
            "mutated_countlocation_result_udas": True,
            "warnings": warnings,
        }
        write_json(json_file, summary_obj)

        out_files = [
            log_file, pass_file, warn_file, uda_file, attr_file,
            detail_file, detail_present_file, summary_file, role_file,
            band_file, worst_file, color_file, readme_file, json_file,
            missing_reserved_file, skipped_link_file, skipped_obs_file,
            skipped_model_file, duplicate_links_file,
        ]

        pass_file.write_text(
            "R1 STEP 12C FLEX CSD2022 GEH COLOR SCALE %s\n"
            "scope=%s\n"
            "present_selected=%d\n"
            "processed=%d\n"
            "missing_reserved=%d\n"
            "skipped_link_not_found=%d\n"
            "skipped_invalid_obs=%d\n"
            "skipped_model_error=%d\n"
            "geh_lt_5=%d\n"
            "geh_lt_10=%d\n"
            "geh_max=%.12g\n"
            "model_scope=%s\n"
            "countlocation_result_udas_written=true\n"
            "assignment_executed_by_script=false\n"
            "version_saved=false\n"
            "output_dir=%s\n" % (
                status,
                scope,
                len(targets),
                len(results),
                len(missing_reserved),
                len(skipped_link),
                len(skipped_obs),
                len(skipped_model),
                summary_all["geh_lt_5"],
                summary_all["geh_lt_5"] + summary_all["geh_5_10"],
                summary_all["geh_max"],
                MODEL_SCOPE,
                str(runtime),
            ),
            encoding="utf-8",
        )

        zip_outputs(latest_zip, out_files)
        log("%s processed=%d selected=%d skipped_link=%d" % (status, len(results), len(targets), len(skipped_link)))

    except Exception:
        tb = traceback.format_exc()
        try:
            err_file.write_text(tb, encoding="utf-8")
        except Exception:
            pass
        try:
            with log_file.open("a", encoding="utf-8") as f:
                f.write("[%s] FAILED; see 12c_flex_ERROR.txt\n" % now_text())
        except Exception:
            pass
        raise


try:
    main()
except Exception:
    raise

# -*- coding: utf-8 -*-
"""
R1 / PTV Visum 2026
STEP 18B2 -- CSD2022 CountLocation GEH scorer for assigned DMC aggregate segment, writing original R1_* fields.

Purpose
-------
Audit results after VISUM Demand Matrix Calibration where the calibrated passenger-car
aggregate is assigned as demand segment R1_OA_CAL_2022.

Default behavior:
  - does NOT execute assignment
  - does NOT run demand, TG/TD, DMC, post-processing or 12C
  - does NOT modify links, matrices, procedures or demand segments
  - does NOT save the .ver file
  - writes original R1_* result UDAs on CountLocations that are present and computable
  - overwrites previous R1_* GEH fields with the DMC aggregate result

Default modelled volume definition:
  model = VOLVEH_DSEG(R1_OA_CAL_2022,AP) on the exact directed link of each CountLocation.

Environment overrides:
  R1_DMC_DSEG=R1_OA_CAL_2022
  R1_18B_SCOPE=reserved_present | all_present_with_r1_obs | all_present

Default scope:
  reserved_present

Run from PTV Visum:
  Scripts -> Run script file -> 18B2_r1_dmc_aggregate_rewrite_r1_geh_countlocations.py
"""
from __future__ import print_function

import csv
import json
import math
import os
import re
import traceback
import zipfile
from datetime import datetime
from pathlib import Path

SCRIPT_ID = "R1_18B2_DMC_AGGREGATE_REWRITE_R1_GEH_20261014"

RESERVED_FIRST = 920001
RESERVED_LAST = 920444
DEFAULT_SCOPE = "reserved_present"
DEFAULT_DSEG = "R1_OA_CAL_2022"

MODEL_SCOPE_PREFIX = "DMC_AGGREGATE_DSEG_DIRECTED_AP"

RESULT_UDA_DEFS = [
    ("R1_MODEL_BOTH", "R1 Model Both", "R1 model passenger value for observation; legacy name", 2, 3),
    ("R1_MODEL_DIR", "R1 Model Dir", "R1 directional model passenger value", 2, 3),
