]

COLOR_BANDS = [
    {"bin": 1, "lower_inclusive": 0.0, "upper_exclusive": 5.0, "band": "<=5", "label": "<= 5", "color_name": "tmave zelena", "hex": "#006400", "rgb": "0,100,0"},
    {"bin": 2, "lower_inclusive": 5.0, "upper_exclusive": 7.5, "band": "<=7.5", "label": "<= 7.5", "color_name": "zelena", "hex": "#14B814", "rgb": "20,184,20"},
